// ---------------------------------------------------------------------------------------------

const areaOf = (nodes, row, col) => {
  const info = nodes[row]?.[col]?.mergeInfo;
  return {
    row,
    col,
    rowSpan: info?.rowSpan || 1,
    colSpan: info?.colSpan || 1
  };
};

// Every merged area (anchor with a span > 1).
const getMergedAreas = nodes => {
  const areas = [];
  nodes.forEach((row, r) => (row || []).forEach((cell, c) => {
    const info = cell?.mergeInfo;
    if (info && info.visible !== false && ((info.rowSpan || 1) > 1 || (info.colSpan || 1) > 1)) areas.push(areaOf(nodes, r, c));
  }));
  return areas;
};
const rectEnd = rect => ({
  rowEnd: rect.row + rect.rowSpan,
  colEnd: rect.col + rect.colSpan
});
const intersects = (a, b) => a.row < b.row + b.rowSpan && b.row < a.row + a.rowSpan && a.col < b.col + b.colSpan && b.col < a.col + a.colSpan;
const sameRect = (a, b) => a.row === b.row && a.col === b.col && a.rowSpan === b.rowSpan && a.colSpan === b.colSpan;

// Grow `rect` until no merged area sticks out of it (so it only ever contains WHOLE areas).
const growToWholeAreas = (areas, rect) => {
  let out = {
    ...rect
  };
  let changed = true;
  while (changed) {
    changed = false;
    for (const a of areas) {
      if (!intersects(out, a)) continue;
      const {
        rowEnd,
        colEnd
      } = rectEnd(out);
      const row = Math.min(out.row, a.row);
      const col = Math.min(out.col, a.col);
      const next = {
        row,
        col,
        rowSpan: Math.max(rowEnd, a.row + a.rowSpan) - row,
        colSpan: Math.max(colEnd, a.col + a.colSpan) - col
      };
      if (!sameRect(next, out)) {
        out = next;
        changed = true;
      }
    }
  }
  return out;
};

// The merged area (or plain 1x1 cell) that owns (row, col).
const findOwningArea = (nodes, areas, row, col) => areas.find(a => intersects(a, {
  row,
  col,
  rowSpan: 1,
  colSpan: 1
})) || areaOf(nodes, row, col);

/**
 * Plan a merge before doing it.
 *
 * @param {Array<Array<Object>>} nodes table matrix
 * @param {Object} op one of
 *   { type: "right" | "left" | "down" | "up", row, col }  — merge the cell (or its area) with its neighbour
 *   { type: "cells", cells: ["r,c", …] }                   — merge a rectangular selection
 *   { type: "row", index } | { type: "column", index }       — merge a whole row / column
 * @returns {{ allowed: boolean, reason?: "nothing" | "splits", rect?: {row,col,rowSpan,colSpan} }}
 *   reason "nothing" = there is nothing to merge (table edge, bad input) — cancel quietly;
 *   reason "splits"  = the merge would cut through another merged cell — cancel and tell the user.
 *   Directional merges may grow ALONG their direction to swallow a whole merged neighbour
 *   (merge right into a 2-wide merged cell takes both columns); they never grow sideways.
 */
const getTableMergePlan = (nodes, op) => {
  const nothing = {
    allowed: false,
    reason: "nothing"
  };
  if (!Array.isArray(nodes) || nodes.length === 0 || !op) return nothing;
  const rowCount = nodes.length;
  const colCount = Math.max(...nodes.map(r => Array.isArray(r) ? r.length : 0));
  const areas = getMergedAreas(nodes);
  let target;
  let fixedAxis = null; // "rows" | "cols" | "both" — what must not change while growing

  if (op.type === "right" || op.type === "left" || op.type === "down" || op.type === "up") {
    if (!nodes[op.row]?.[op.col]) return nothing;
    const main = findOwningArea(nodes, areas, op.row, op.col);
    const end = rectEnd(main);
    if (op.type === "right") {
      if (end.colEnd >= colCount) return nothing;
      target = {
        ...main,
        colSpan: main.colSpan + 1
      };
    } else if (op.type === "left") {
      if (main.col <= 0) return nothing;
      target = {
        ...main,
        col: main.col - 1,
        colSpan: main.colSpan + 1
      };
    } else if (op.type === "down") {
      if (end.rowEnd >= rowCount) return nothing;
      target = {
        ...main,
        rowSpan: main.rowSpan + 1
      };
    } else {
      if (main.row <= 0) return nothing;
      target = {
        ...main,
        row: main.row - 1,
        rowSpan: main.rowSpan + 1
      };
    }
    fixedAxis = op.type === "right" || op.type === "left" ? "rows" : "cols";
  } else if (op.type === "cells") {
    const coords = (op.cells || []).map(k => String(k).split(",").map(Number)).filter(([r, c]) => Number.isInteger(r) && Number.isInteger(c));
    if (coords.length < 2) return nothing;
    const rows = coords.map(([r]) => r);
    const cols = coords.map(([, c]) => c);
    const row = Math.min(...rows);
    const col = Math.min(...cols);
    target = {
      row,
      col,
      rowSpan: Math.max(...rows) - row + 1,
      colSpan: Math.max(...cols) - col + 1
    };
    if (target.row + target.rowSpan > rowCount || target.col + target.colSpan > colCount) return nothing;
    // The selection must FILL its bounding box — every cell in it selected, or covered by a
    // merged cell whose anchor is selected. Otherwise (e.g. Ctrl-picked corners) it's not a
    // rectangle and nothing is merged — never the unselected cells in between.
    const selected = new Set(coords.map(([r, c]) => `${r},${c}`));
    for (let r = target.row; r < target.row + target.rowSpan; r++) {
      for (let c = target.col; c < target.col + target.colSpan; c++) {
        if (selected.has(`${r},${c}`)) continue;
        const owner = areas.find(a => intersects(a, {
          row: r,
          col: c,
          rowSpan: 1,
          colSpan: 1
        }));
        if (!owner || !selected.has(`${owner.row},${owner.col}`)) return nothing;
      }
    }
    fixedAxis = "both";
  } else if (op.type === "row") {
    if (!(op.index >= 0 && op.index < rowCount) || colCount < 2) return nothing;
    target = {
      row: op.index,
      col: 0,
      rowSpan: 1,
      colSpan: colCount
    };
    fixedAxis = "both";
  } else if (op.type === "column") {
    if (!(op.index >= 0 && op.index < colCount) || rowCount < 2) return nothing;
    target = {
      row: 0,
      col: op.index,
      rowSpan: rowCount,
      colSpan: 1
    };
    fixedAxis = "both";
  } else {
    return nothing;
  }
  const grown = growToWholeAreas(areas, target);
  const rowsChanged = grown.row !== target.row || grown.rowSpan !== target.rowSpan;
  const colsChanged = grown.col !== target.col || grown.colSpan !== target.colSpan;
  if (fixedAxis !== "cols" && rowsChanged || fixedAxis !== "rows" && colsChanged) return {
    allowed: false,
    reason: "splits"
  };
  if (grown.rowSpan * grown.colSpan < 2) return nothing;
  // Already exactly one merged area (e.g. merge a row that is already fully merged).
  if (areas.some(a => sameRect(a, grown))) return nothing;
  return {
    allowed: true,
    rect: grown
  };
};

/**
 * Merge `rect` into one cell: the top-left cell becomes the anchor, every other cell in the rect is
 * covered (spans reset). Returns a NEW matrix (cells in the rect are copied, others shared).
 * Only call with a rect from getTableMergePlan (it contains whole merged areas only).
 */
const applyTableMerge = (nodes, rect) => {
  const next = nodes.map(row => [...row]);
  for (let r = rect.row; r < rect.row + rect.rowSpan; r++) {
    for (let c = rect.col; c < rect.col + rect.colSpan; c++) {
      const cell = next[r]?.[c];
      if (!cell) continue;
      const isAnchor = r === rect.row && c === rect.col;
      next[r][c] = {
        ...cell,
        mergeInfo: isAnchor ? {
          ...cell.mergeInfo,
          visible: true,
          rowSpan: rect.rowSpan,
          colSpan: rect.colSpan
        } : {
          ...cell.mergeInfo,
          visible: false,
          rowSpan: 1,
          colSpan: 1
        }
      };
    }
  }
  return next;
};

/**
 * Unmerge every merged area that touches `rect` — the WHOLE area, so a covered cell never becomes
 * visible while its anchor still spans over it. Always valid; returns a NEW matrix.
 * rect: a cell { row, col, rowSpan: 1, colSpan: 1 }, a whole row or a whole column.
 */
const unmergeTableAreas = (nodes, rect) => {
  const areas = getMergedAreas(nodes).filter(a => intersects(a, rect));
  if (areas.length === 0) return nodes;
  const next = nodes.map(row => [...row]);
  areas.forEach(a => {
    for (let r = a.row; r < a.row + a.rowSpan; r++) {
      for (let c = a.col; c < a.col + a.colSpan; c++) {
        const cell = next[r]?.[c];
        if (cell) next[r][c] = {
          ...cell,
          mergeInfo: {
            ...cell.mergeInfo,
            visible: true,
            rowSpan: 1,
            colSpan: 1
          }
        };
      }
    }
  });
  return next;
};

/**
 * Delete a whole row / column without breaking merged cells. Returns a NEW matrix, re-indexed.
 * Per merged cell that spans the deleted line (along the delete direction):
 *   - the line is inside it but not its first line → it shrinks by one
 *   - the line is its first line (the anchor's) → the merged cell — content and style — moves to
 *     the next line, one smaller (so its text isn't lost with the deleted line)
 *   - it lies entirely in the deleted line → it simply goes with the line
 * The old delete only filtered the line out: the merge kept its span (covering one line too many)
 * or its covered cells lost their anchor — either way the following rows/columns shifted.
 * Callers keep their own "never delete the last row/column" guard.
 */
const deleteTableLine = (nodes, direction, index) => {
  if (!Array.isArray(nodes) || nodes.length === 0) return nodes;
  const isRow = direction === "row";
  const next = nodes.map(row => [...row]);
  getMergedAreas(nodes).forEach(a => {
    const start = isRow ? a.row : a.col;
    const span = isRow ? a.rowSpan : a.colSpan;
    if (span < 2 || index < start || index >= start + span) return;
    const shrunk = isRow ? {
      rowSpan: span - 1,
      colSpan: a.colSpan
    } : {
      rowSpan: a.rowSpan,
      colSpan: span - 1
    };
    const anchor = nodes[a.row][a.col];
    if (index !== start) {
      next[a.row][a.col] = {
        ...anchor,
        mergeInfo: {
          ...anchor.mergeInfo,
          ...shrunk
        }
      };
    } else {
      const [r, c] = isRow ? [a.row + 1, a.col] : [a.row, a.col + 1];
      if (next[r]?.[c]) next[r][c] = {
        ...anchor,
        mergeInfo: {
          ...anchor.mergeInfo,
          visible: true,
          ...shrunk
        }
      };
    }
  });
  const reindex = (cell, row, col) => cell ? {
    ...cell,
    rowIndex: row,
    colIndex: col,
    id: `table-cell-${row}-${col}`,
    data: {
      ...cell.data,
      position: {
        row,
        col
      },
      cellId: `cell-${row}-${col}`
    }
  } : cell;
  const kept = isRow ? next.filter((_, r) => r !== index) : next.map(row => row.filter((_, c) => c !== index));
  return kept.map((row, r) => row.map((cell, c) => reindex(cell, r, c)));
};

// Helper function to create a cell object

// Helper function to check if a cell is visible
const isCellVisible = cell => {
  return cell.mergeInfo && cell.mergeInfo.visible !== false;
};

// Helper function to get cell text content
const getCellText = cell => {
  return cell.content?.text || "";
};

// Helper function to check if a cell is merged
const isCellMerged = cell => {
  return cell.mergeInfo && (cell.mergeInfo.rowSpan > 1 || cell.mergeInfo.colSpan > 1);
};

/**
 * How to swap two rows (or two columns) without breaking merged cells.
 *
 * Covered cells only carry `mergeInfo.visible: false` — the merge lives on its anchor cell
 * (rowSpan/colSpan > 1) — so a plain whole-line swap moves anchors and covered cells apart:
 * swapping the two rows of a rowSpan-2 cell pushes the anchor one row down, the merge then
 * covers the NEXT row too and that row's cells shift one column right.
 *
 * Per merged cell that spans more than one line along the swap direction:
 *   - it covers BOTH lines  → it stays where it is; only the other cells of the two lines swap
 *                             (`keep` lists the cross-axis indexes to leave in place)
 *   - it covers ONE of them → the swap would split it → `allowed: false`
 * A merge inside a single line (e.g. colSpan on the moving row) simply moves with its line.
 *
 * @param {Array<Array<Object>>} nodes table matrix (rows of cells with mergeInfo)
 * @param {"row"|"column"} direction
 * @returns {{ allowed: boolean, keep: Set<number> }}
 */
const getTableSwapPlan = (nodes, direction, fromIndex, toIndex) => {
  const keep = new Set();
  if (!Array.isArray(nodes) || fromIndex === toIndex) return {
    allowed: true,
    keep
  };
  const isRow = direction === "row";
  for (let r = 0; r < nodes.length; r++) {
    const row = Array.isArray(nodes[r]) ? nodes[r] : [];
    for (let c = 0; c < row.length; c++) {
      const info = row[c]?.mergeInfo;
      if (!info || info.visible === false) continue;
      const rowSpan = info.rowSpan || 1;
      const colSpan = info.colSpan || 1;
      // extent along the swap axis, and across it
      const [start, span, crossStart, crossSpan] = isRow ? [r, rowSpan, c, colSpan] : [c, colSpan, r, rowSpan];
      if (span < 2) continue;
      const coversFrom = fromIndex >= start && fromIndex < start + span;
      const coversTo = toIndex >= start && toIndex < start + span;
      if (coversFrom && coversTo) {
        for (let k = crossStart; k < crossStart + crossSpan; k++) keep.add(k);
      } else if (coversFrom || coversTo) {
        return {
          allowed: false,
          keep: new Set()
        };
      }
    }
  }
  return {
    allowed: true,
    keep
  };
};

// ---------------------------------------------------------------------------------------------
// Element paths — every element inside a cell carries `path` = "table[r][c]…" (data.path and
// properties.path, also nested group/logo paths). Edits find their cell FROM that string: the
// text element sends `elementPath: data.path` and the table reducers parse table[r][c] out of it.
// Moving cells (swap / insert / delete / duplicate) never rewrote them, so after e.g. a row swap
// bolding the moved "International" bolded the cell now sitting at its OLD position instead.
// ---------------------------------------------------------------------------------------------
const TABLE_PATH_PREFIX = /^table\[\d+\]\[\d+\]/;

// Rewrite every `path` string under `value` to start with `prefix`. Copies only what changes.
const rewriteTablePaths = (value, prefix) => {
  if (Array.isArray(value)) {
    let changed = false;
    const out = value.map(item => {
      const next = rewriteTablePaths(item, prefix);
      if (next !== item) changed = true;
      return next;
    });
    return changed ? out : value;
  }
  if (!value || typeof value !== "object") return value;
  let out = null;
  Object.keys(value).forEach(key => {
    const item = value[key];
    let next = item;
    if (key === "path" && typeof item === "string") {
      if (TABLE_PATH_PREFIX.test(item)) next = item.replace(TABLE_PATH_PREFIX, prefix);
    } else if (item && typeof item === "object") {
      next = rewriteTablePaths(item, prefix);
    }
    if (next !== item) {
      if (!out) out = {
        ...value
      };
      out[key] = next;
    }
  });
  return out || value;
};

/**
 * Point every element path in the matrix at the cell's REAL position (table[r][c]…). Run after any
 * operation that moves cells. Returns the same array when nothing needed fixing.
 */
const fixTablePaths = nodes => {
  if (!Array.isArray(nodes)) return nodes;
  let changed = false;
  const out = nodes.map((row, r) => {
    if (!Array.isArray(row)) return row;
    let rowChanged = false;
    const nextRow = row.map((cell, c) => {
      const next = cell ? rewriteTablePaths(cell, `table[${r}][${c}]`) : cell;
      if (next !== cell) rowChanged = true;
      return next;
    });
    if (!rowChanged) return row;
    changed = true;
    return nextRow;
  });
  return changed ? out : nodes;
};

// Helper function to get all cells in a selection range
const getCellsInSelectionRange = (data, startRow, endRow, startCol, endCol) => {
  const cellKeys = [];
  for (let r = startRow; r <= endRow; r++) {
    for (let c = startCol; c <= endCol; c++) {
      if (isCellVisible(data[r][c])) {
        cellKeys.push(`${r},${c}`);
      }
    }
  }
  return cellKeys;
};

// Helper function to expand selection to include merged cells
const expandSelectionForMergedCells = (data, cellKeys) => {
  const expandedSelection = new Set(cellKeys);
  cellKeys.forEach(cellKey => {
    const [rowIndex, colIndex] = cellKey.split(",").map(Number);
    const cell = data[rowIndex][colIndex];
    if (isCellMerged(cell)) {
      const rowSpan = cell.mergeInfo?.rowSpan || 1;
      const colSpan = cell.mergeInfo?.colSpan || 1;

      // Add all cells in the merged span
      for (let r = rowIndex; r < rowIndex + rowSpan; r++) {
        for (let c = colIndex; c < colIndex + colSpan; c++) {
          expandedSelection.add(`${r},${c}`);
        }
      }
    }
  });
  return Array.from(expandedSelection);
};
const getTextObjectFromCell = cell => {

  // find text object from cell
  // the object may nested in other objects, so we need to find the text object recursively.
  // gothrough all keys check the valuse object or array, if it is object, check the keys recursively.
  // if it is array, check the elements recursively.
  // if it is text object, return the text object.
  // if it is not text object, return null.
  if (cell.type === "text") {
    return cell;
  }
  let textObject = null;
  for (let key in cell) {
    if (typeof cell[key] === "object") {
      textObject = getTextObjectFromCell(cell[key]);
      if (textObject) {
        break;
      }
    }
    if (Array.isArray(cell[key])) {
      textObject = getTextObjectFromCell(cell[key]);
      if (textObject) {
        break;
      }
    }
  }
  return textObject;
};

