// Defaults mapped from the graphite mood's font-class mapping
// (graphite-font-class-mapping.json). The `diagram` block drives node text
// subtypes and the `chart` block drives axislabel; keys graphite doesn't define
// (badge, section, caption, quadrantlabel) fall back to the nearest analog.
const TEXT_FONT_SIZE_MAPPING = {
  heading: "h8",
  // graphite diagram.heading
  body: "p4",
  // graphite diagram.body
  label: "l2",
  // graphite diagram.label
  subheading: "p3",
  // graphite diagram.subheading
  sequence: "n8",
  // graphite diagram.sequence
  "data-driven": "n5",
  // graphite diagram.data-driven
  graphictitle: "h8",
  // graphite diagram.graphictitle
  graphicsource: "p8",
  // graphite diagram.graphicsource
  button: "p8",
  // graphite diagram.button
  "micro-label": "n7",
  // graphite diagram.micro-label
  quote: "q3",
  // graphite diagram.quote
  badge: "l2",
  // graphite-undefined → label analog
  testimonial: "q3",
  // graphite diagram.testimonial
  section: "h8",
  // graphite-undefined → heading analog
  caption: "p8",
  // graphite-undefined → source/caption analog
  quadrantlabel: "h9",
  // graphite-undefined → chart axis analog
  axislabel: "h9" // graphite chart.axislabel
};

// Ordered font-size classes, largest -> smallest, grouped by series (h*, then p*, then n*).
// Used by text auto-fit: when text overflows its container the font steps DOWN to the
// next entry in this list, but only within the same series (an h-class never crosses
// into p-classes, a p-class never crosses into n1). The list is contiguous per series,
// so "next index" naturally stays in-series until the series boundary.
const FONT_CLASSLIST = ["h1", "h1 h1_1", "h2", "h2 h2_1", "h3", "h3 h3_1", "h3 h3_2", "h4", "h4 h4_1", "h5", "h5 h5_1", "h5 h5_2", "h6", "h6 h6_1", "h7", "h7 h7_1", "h8", "h9", "h9 h9_1", "h10", "h10 h10_1", "h11", "h11 h11_1", "h11 h11_2", "h11 h11_3", "h11 h11_4", "h11 h11_5", "h11 h11_6", "p1", "p1 p1_1", "p2", "p3", "p4", "p5", "p6", "p7", "p8", "p9", "p9 p9_1", "p9 p9_2", "p9 p9_3", "p9 p9_4", "p9 p9_5", "p9 p9_6", "n1"];

// The "series" of a font class is the leading alpha prefix of its first token:
//   "h11 h11_4" -> "h", "p9 p9_2" -> "p", "n1" -> "n".
// All h1..h11 collapse to "h" and all p1..p9 collapse to "p", so step-down stays
// within heading- or paragraph-sized classes respectively.
const getFontSeries = fontClass => {
  if (!fontClass || typeof fontClass !== "string") return "";
  const firstToken = fontClass.trim().split(/\s+/)[0] || "";
  const match = firstToken.match(/^[a-zA-Z]+/);
  return match ? match[0] : "";
};

// Build the ordered list of step-down candidates starting AT `fontClass`, staying
// within the same series: returns [current, nextSmaller, nextSmaller, ...].
// Falls back to [fontClass] when the class isn't a known FONT_CLASSLIST entry, and
// to [] when there's no usable class.
const getFontStepDownChain = fontClass => {
  const normalized = typeof fontClass === "string" ? fontClass.trim().replace(/\s+/g, " ") : "";
  const startIndex = FONT_CLASSLIST.indexOf(normalized);
  if (startIndex === -1) return normalized ? [normalized] : [];
  const series = getFontSeries(normalized);
  const chain = [];
  for (let i = startIndex; i < FONT_CLASSLIST.length; i++) {
    if (getFontSeries(FONT_CLASSLIST[i]) !== series) break;
    chain.push(FONT_CLASSLIST[i]);
  }
  return chain;
};
