const generateRichTableCellPatternFloaterConfig = (cell, rowIndex, cellIndex, rows, cellType = "data") => {
  const nodealignOpts = getNodeAlignOptions(cell?.nodealign || "center");
  nodealignOpts.floaterproperty = "RICHTABLE_NODE_ALIGN";
  const result = {
    changecellpattern: {
      label: "Pattern",
      floaterproperty: "CELL_PATTERN_CHANGE"
    },
    cellBgColor: {
      floaterproperty: "RICHTABLE_CELL_BG_COLOR",
      label: "Cell Background Color",
      action: "RICHTABLE_CELL_BG_COLOR",
      type: "color"
    },
    nodealign: nodealignOpts
  };
  const mergeInfo = cell?.mergeInfo;
  const currentColSpan = mergeInfo?.colSpan || 1;
  const currentRowSpan = mergeInfo?.rowSpan || 1;
  const isMerged = currentColSpan > 1 || currentRowSpan > 1;
  const colCount = rows[0]?.cells?.length || 0;
  const rowCount = rows.length;
  const mergeSources = [];
  if (cellType === "header") {
    // Header row: horizontal merge only
    if (cellIndex > 0) {
      mergeSources.push({
        property: "mergeLeft",
        data: "mergeLeft",
        label: "mergeLeft",
        value: false,
        visible: true
      });
    }
    if (cellIndex + currentColSpan < colCount) {
      mergeSources.push({
        property: "mergeRight",
        data: "mergeRight",
        label: "mergeRight",
        value: false,
        visible: true
      });
    }
  } else if (cellType === "entity") {
    // Entity column: vertical merge only
    if (rowIndex > 0) {
      mergeSources.push({
        property: "mergeUp",
        data: "mergeUp",
        label: "mergeUp",
        value: false,
        visible: true
      });
    }
    if (rowIndex + currentRowSpan < rowCount) {
      mergeSources.push({
        property: "mergeDown",
        data: "mergeDown",
        label: "mergeDown",
        value: false,
        visible: true
      });
    }
  } else {
    // Data cell: all directions
    if (cellIndex > 0 && rows[rowIndex]?.cells[cellIndex - 1] != null) {
      mergeSources.push({
        property: "mergeLeft",
        data: "mergeLeft",
        label: "mergeLeft",
        value: false,
        visible: true
      });
    }
    if (rowIndex > 0 && rows[rowIndex - 1]?.cells[cellIndex] != null) {
      mergeSources.push({
        property: "mergeUp",
        data: "mergeUp",
        label: "mergeUp",
        value: false,
        visible: true
      });
    }
    if (cellIndex + currentColSpan < colCount) {
      mergeSources.push({
        property: "mergeRight",
        data: "mergeRight",
        label: "mergeRight",
        value: false,
        visible: true
      });
    }
    if (rowIndex + currentRowSpan < rowCount) {
      mergeSources.push({
        property: "mergeDown",
        data: "mergeDown",
        label: "mergeDown",
        value: false,
        visible: true
      });
    }
  }
  if (isMerged) {
    mergeSources.push({
      property: "unmerge",
      data: "unmerge",
      label: "unmerge",
      value: false,
      visible: true
    });
  }
  if (mergeSources.length > 0) {
    result.mergeOption = {
      floaterproperty: "RICH_TABLE_MERGE",
      dpsource: mergeSources,
      selectedindex: -1,
      label: "mergeoptions"
    };
  }
  return result;
};
