// Function to calculate scale based on SVG viewBox and container and apply appropriate styling
DiagramHelper.calculateSvgScale = function (svgElement, container, numSlideScale) {
  if (!svgElement || !container) return 1;
  const viewBox = svgElement.getAttribute("viewBox");
  if (!viewBox) {
    // Fallback if no viewBox
    svgElement.style.width = "100%";
    svgElement.style.height = "100%";
    return 1;
  }
  const [x, y, width, height] = viewBox.split(" ").map(Number);

  // Adjust container dimensions by slide scale to get the actual intended size
  const actualContainerWidth = container.offsetWidth;
  const actualContainerHeight = container.offsetHeight;

  // Calculate scale factors for both width and height using actual container size
  const scaleX = Number((actualContainerWidth / width).toFixed(2));
  const scaleY = Number((actualContainerHeight / height).toFixed(2));
  const scaleXFloat = Number(actualContainerWidth / width);
  const scaleYFloat = Number(actualContainerHeight / height);

  // Use the smaller scale to maintain aspect ratio
  const svgScale = Math.min(scaleX, scaleY);

  // Apply appropriate styling based on which dimension is the limiting factor
  if (scaleX < scaleY || scaleX == scaleY || numSlideScale == 1) {
    // Width is the limiting factor
    svgElement.style.width = "100%";
    svgElement.style.height = "auto";
  } else {
    // Height is the limiting factor
    svgElement.style.width = "auto";
    svgElement.style.height = "100%";
  }

  // Return the final scale (SVG scale * slide scale)
  return svgScale == scaleX ? scaleXFloat : scaleYFloat;
};

