  templateContainer.style.setProperty("--nl-template-padding-right", offsetValuesArray[1] + DiagramHelper.getSuffixValue(offsetValuesArray[1]) || "0px");
  templateContainer.style.setProperty("--nl-template-padding-bottom", offsetValuesArray[2] + DiagramHelper.getSuffixValue(offsetValuesArray[2]) || "0px");
  templateContainer.style.setProperty("--nl-template-padding-left", offsetValuesArray[3] + DiagramHelper.getSuffixValue(offsetValuesArray[3]) || "0px");
